import React, { useState } from "react";
import { X, Send, Check, MessageCircle } from "lucide-react";
import { COLLECTIONS } from "./Content";

export default function QuoteModal({ isOpen, onClose }) {
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: "",
    eventType: "",
    message: "",
    categories: [],
  });
  const [submitted, setSubmitted] = useState(false);

  if (!isOpen) return null;

  const eventTypes = [
    "Wedding",
    "Corporate Event",
    "Birthday Party",
    "Festival Celebration",
    "Other",
  ];

  const handleCategoryToggle = (categoryId) => {
    setFormData((prev) => ({
      ...prev,
      categories: prev.categories.includes(categoryId)
        ? prev.categories.filter((id) => id !== categoryId)
        : [...prev.categories, categoryId],
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Build WhatsApp message
    const selectedCategories = formData.categories
      .map((id) => {
        const cat = COLLECTIONS.find((c) => c.id === id);
        return cat ? cat.title : "";
      })
      .filter(Boolean)
      .join(", ");

    const message = `*New Quote Request - D SAJAWAT*

*Name:* ${formData.name}
*Phone:* ${formData.phone}
*Email:* ${formData.email}
*Event Type:* ${formData.eventType}
*Interested Categories:* ${selectedCategories || "General Inquiry"}
*Message:* ${formData.message || "None"}`;

    const whatsappUrl = `https://wa.me/919888919983?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, "_blank");

    setSubmitted(true);
    setTimeout(() => {
      onClose();
      setSubmitted(false);
      setFormData({
        name: "",
        phone: "",
        email: "",
        eventType: "",
        message: "",
        categories: [],
      });
    }, 2000);
  };

  const handleWhatsAppDirect = () => {
    const message = `Hi! I'm interested in D SAJAWAT fabrics and would like to discuss a quote.`;
    const whatsappUrl = `https://wa.me/919888919983?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, "_blank");
  };

  return (
    <div
      className="fixed inset-0 z-[100] flex items-center justify-center p-4"
      data-testid="quote-modal"
    >
      {/* Backdrop */}
      <div
        className="absolute inset-0"
        style={{ background: "rgba(0, 0, 0, 0.85)", backdropFilter: "blur(8px)" }}
        onClick={onClose}
      />

      {/* Modal */}
      <div
        className="relative w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-sm"
        style={{
          background: "linear-gradient(180deg, #1a080a 0%, #0d0405 100%)",
          border: "1px solid rgba(212, 175, 55, 0.4)",
          boxShadow: "0 0 60px rgba(212, 175, 55, 0.15)",
        }}
      >
        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 p-2 rounded-full transition-all duration-200 hover:bg-white/10"
          data-testid="modal-close-btn"
        >
          <X size={20} color="#f7e7ce" />
        </button>

        {submitted ? (
          /* Success State */
          <div className="flex flex-col items-center justify-center py-16 px-8">
            <div
              className="w-16 h-16 rounded-full flex items-center justify-center mb-6"
              style={{ background: "rgba(212, 175, 55, 0.2)", border: "1px solid #d4af37" }}
            >
              <Check size={32} color="#d4af37" />
            </div>
            <h3
              className="serif text-3xl mb-3"
              style={{ color: "#fffff0" }}
            >
              Request Sent!
            </h3>
            <p style={{ color: "rgba(255,255,240,0.7)", textAlign: "center" }}>
              We'll connect with you on WhatsApp shortly.
            </p>
          </div>
        ) : (
          /* Form */
          <form onSubmit={handleSubmit} className="p-8 md:p-10">
            <div className="mb-8">
              <div className="overline mb-2">Get a Quote</div>
              <h2
                className="serif"
                style={{
                  fontSize: "clamp(28px, 4vw, 42px)",
                  fontWeight: 300,
                  color: "#fffff0",
                }}
              >
                Let's decorate your event
              </h2>
            </div>

            {/* Quick WhatsApp Option */}
            <div
              className="mb-8 p-5 rounded-sm flex items-center justify-between"
              style={{
                background: "rgba(37, 211, 102, 0.1)",
                border: "1px solid rgba(37, 211, 102, 0.3)",
              }}
            >
              <div>
                <p style={{ color: "#fffff0", fontWeight: 500 }}>
                  Need quick response?
                </p>
                <p className="text-sm mt-1" style={{ color: "rgba(255,255,240,0.6)" }}>
                  Chat directly on WhatsApp
                </p>
              </div>
              <button
                type="button"
                onClick={handleWhatsAppDirect}
                className="flex items-center gap-2 px-5 py-3 rounded-full text-sm font-medium transition-all"
                style={{
                  background: "linear-gradient(135deg, #25d366 0%, #128c7e 100%)",
                  color: "white",
                }}
                data-testid="whatsapp-direct-btn"
              >
                <MessageCircle size={18} />
                Chat Now
              </button>
            </div>

            {/* Form Fields */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mb-6">
              <div>
                <label
                  className="block text-xs tracking-widest uppercase mb-2"
                  style={{ color: "rgba(212, 175, 55, 0.8)" }}
                >
                  Your Name *
                </label>
                <input
                  type="text"
                  required
                  className="field"
                  placeholder="Enter your name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  data-testid="quote-name-input"
                />
              </div>

              <div>
                <label
                  className="block text-xs tracking-widest uppercase mb-2"
                  style={{ color: "rgba(212, 175, 55, 0.8)" }}
                >
                  Phone Number *
                </label>
                <input
                  type="tel"
                  required
                  className="field"
                  placeholder="Your phone number"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  data-testid="quote-phone-input"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mb-6">
              <div>
                <label
                  className="block text-xs tracking-widest uppercase mb-2"
                  style={{ color: "rgba(212, 175, 55, 0.8)" }}
                >
                  Email
                </label>
                <input
                  type="email"
                  className="field"
                  placeholder="Your email (optional)"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  data-testid="quote-email-input"
                />
              </div>

              <div>
                <label
                  className="block text-xs tracking-widest uppercase mb-2"
                  style={{ color: "rgba(212, 175, 55, 0.8)" }}
                >
                  Event Type *
                </label>
                <select
                  required
                  className="field"
                  value={formData.eventType}
                  onChange={(e) => setFormData({ ...formData, eventType: e.target.value })}
                  data-testid="quote-event-select"
                  style={{
                    background: "rgba(255, 255, 240, 0.03)",
                    border: "1px solid rgba(212, 175, 55, 0.25)",
                    color: formData.eventType ? "#fffff0" : "rgba(255, 255, 240, 0.35)",
                  }}
                >
                  <option value="" disabled>
                    Select event type
                  </option>
                  {eventTypes.map((type) => (
                    <option key={type} value={type} style={{ background: "#1a080a" }}>
                      {type}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Category Selection */}
            <div className="mb-6">
              <label
                className="block text-xs tracking-widest uppercase mb-3"
                style={{ color: "rgba(212, 175, 55, 0.8)" }}
              >
                Interested Products
              </label>
              <div className="flex flex-wrap gap-3">
                {COLLECTIONS.map((cat) => (
                  <button
                    key={cat.id}
                    type="button"
                    onClick={() => handleCategoryToggle(cat.id)}
                    className="px-4 py-2 rounded-full text-xs tracking-wider transition-all duration-200"
                    style={{
                      background: formData.categories.includes(cat.id)
                        ? "linear-gradient(135deg, #d4af37 0%, #f7e7ce 100%)"
                        : "transparent",
                      color: formData.categories.includes(cat.id)
                        ? "#1a080a"
                        : "rgba(255, 255, 240, 0.7)",
                      border: formData.categories.includes(cat.id)
                        ? "1px solid transparent"
                        : "1px solid rgba(212, 175, 55, 0.4)",
                      fontWeight: 500,
                    }}
                    data-testid={`quote-category-${cat.id}`}
                  >
                    {cat.title}
                  </button>
                ))}
              </div>
            </div>

            {/* Message */}
            <div className="mb-8">
              <label
                className="block text-xs tracking-widest uppercase mb-2"
                style={{ color: "rgba(212, 175, 55, 0.8)" }}
              >
                Your Message
              </label>
              <textarea
                className="field"
                rows={4}
                placeholder="Tell us about your requirements - quantities, measurements, event date..."
                value={formData.message}
                onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                data-testid="quote-message-input"
                style={{ resize: "vertical", minHeight: 100 }}
              />
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              className="btn-gold w-full justify-center"
              data-testid="quote-submit-btn"
            >
              <Send size={18} strokeWidth={1.6} />
              Send Quote Request via WhatsApp
            </button>

            <p
              className="text-center mt-4 text-xs"
              style={{ color: "rgba(255, 255, 240, 0.5)" }}
            >
              We'll respond within 24 hours
            </p>
          </form>
        )}
      </div>
    </div>
  );
}
